import { z } from "zod"

const AgendaItem = z.strictObject({
  id: z.string(),
  label: z.string(),
})

const WidgetState = z.strictObject({
  meetingId: z.string(),
  title: z.string(),
  time: z.string(),
  attendees: z.array(z.string()).min(1),
  agenda: z.array(AgendaItem).length(3),
})

export default WidgetState

import { z } from "zod"

const Action = z.strictObject({
  type: z.string(),
  payload: z.record(z.unknown()).optional(),
  handler: z.enum(["server", "client"]).optional(),
  loadingBehavior: z.enum(["auto", "none", "self", "container"]).optional(),
})

const Step = z.strictObject({
  id: z.string(),
  label: z.string(),
  done: z.boolean(),
})

const Stats = z.strictObject({
  done: z.number(),
  total: z.number(),
  percent: z.number(),
})

const CTA = z.strictObject({
  label: z.string(),
  action: Action,
})

const WidgetState = z.strictObject({
  userName: z.string(),
  steps: z.array(Step),
  stats: Stats,
  nextAction: CTA,
  help: CTA,
})

export default WidgetState

import { z } from "zod"

const BadgeColor = z.enum(["secondary", "success", "danger", "warning", "info", "discovery"])

const Interviewer = z.strictObject({
  id: z.string(),
  name: z.string(),
})

const WidgetState = z.strictObject({
  candidate: z.strictObject({
    id: z.string(),
    name: z.string(),
    role: z.string(),
  }),
  stage: z.strictObject({
    label: z.string(),
    color: BadgeColor,
  }),
  scorecards: z.strictObject({
    submitted: z.number(),
    total: z.number(),
    statusLabel: z.string(),
    statusColor: BadgeColor,
  }),
  interviewers: z.array(Interviewer),
})

export default WidgetState

import { z } from "zod"

const Benefit = z.strictObject({
  id: z.string(),
  text: z.string(),
})

const CurrentPlan = z.strictObject({
  id: z.string(),
  name: z.string(),
  price: z.string(),
  usageLabel: z.string(),
})

const UpgradePlan = z.strictObject({
  id: z.string(),
  name: z.string(),
  price: z.string(),
  benefits: z.array(Benefit),
})

const WidgetState = z.strictObject({
  title: z.string(),
  current: CurrentPlan,
  upgrade: UpgradePlan,
})

export default WidgetState

import { z } from "zod"

